18	// Managed plugin storage. The kubectl-style dispatcher in plugin.go resolves
19	// `entire-<name>` binaries from $PATH, period. To let `entire plugin install`
20	// be additive rather than a parallel mechanism, this file provides:
21	//
22	//  1. PluginBinDir() — a per-user managed dir that main.go prepends to PATH
23	//     before the dispatcher runs. Anything dropped here (or symlinked here)
24	//     becomes invocable as `entire <name>` without the user fiddling with PATH.
25	//
26	//  2. PluginDataDir(name) — a per-plugin durable storage dir, passed to plugins
27	//     as ENTIRE_PLUGIN_DATA_DIR. Independent of where the binary itself lives
28	//     so plugins installed via PATH and via the managed dir get the same
29	//     contract.
30	//
31	// Honors ENTIRE_PLUGIN_DIR as a parent-dir override; falls back to
32	// XDG_DATA_HOME, then a platform default.
33	
34	const (
35		pluginEnvPluginDir      = "ENTIRE_PLUGIN_DIR"
36		pluginManagedBinSubdir  = "bin"
37		pluginManagedDataSubdir = "data"
38		pluginEnvPluginData     = "ENTIRE_PLUGIN_DATA_DIR"
39		// Path segments for the managed plugin tree. Kept as separate
40		// segments (rather than "entire/plugins") so filepath.Join produces
41		// platform-native separators on Windows.
42		pluginManagedTopDir = "entire"
43		pluginManagedSubDir = "plugins"
44	)
45	
46	// pluginParentDir returns the per-user directory that holds the managed
47	// plugin storage. Resolution, in order:
48	//
49	//  1. ENTIRE_PLUGIN_DIR (cross-platform override).
50	//  2. On Windows: LOCALAPPDATA if set, else ~\AppData\Local\entire\plugins.
51	//  3. On Unix: XDG_DATA_HOME if set, else ~/.local/share/entire/plugins.
52	//
53	// XDG_DATA_HOME is deliberately ignored on Windows even when set (e.g. in
54	// MSYS/Cygwin) — Windows users expect Windows conventions, and routing
55	// through XDG would produce a surprising location.
56	//
57	// os.UserHomeDir is called only when no env-var branch resolves, so a
58	// degenerate environment with $LOCALAPPDATA or $XDG_DATA_HOME but no home
59	// still returns a usable path.
60	func pluginParentDir() (string, error) {
61		if v := os.Getenv(pluginEnvPluginDir); v != "" {
62			return v, nil
63		}
64		if runtime.GOOS == windowsGOOS {
65			if appData := os.Getenv("LOCALAPPDATA"); appData != "" {
66				return filepath.Join(appData, pluginManagedTopDir, pluginManagedSubDir), nil
67			}
68			home, err := os.UserHomeDir()
69			if err != nil {
70				return "", fmt.Errorf("resolve home dir: %w", err)
71			}
72			return filepath.Join(home, "AppData", "Local", pluginManagedTopDir, pluginManagedSubDir), nil
73		}
74		if v := os.Getenv("XDG_DATA_HOME"); v != "" {
75			return filepath.Join(v, pluginManagedTopDir, pluginManagedSubDir), nil
76		}
77		home, err := os.UserHomeDir()
78		if err != nil {
79			return "", fmt.Errorf("resolve home dir: %w", err)
80		}
81		return filepath.Join(home, ".local", "share", pluginManagedTopDir, pluginManagedSubDir), nil
82	}
