84	// PluginBinDir returns the managed install directory. Binaries (or symlinks)
85	// placed here are auto-discovered by the kubectl-style dispatcher because
86	// main.go prepends this dir to PATH before MaybeRunPlugin runs.
87	func PluginBinDir() (string, error) {
88		parent, err := pluginParentDir()
89		if err != nil {
90			return "", err
91		}
92		return filepath.Join(parent, pluginManagedBinSubdir), nil
93	}
