95	// PluginDataDir returns the per-plugin data directory for the given bare name
96	// (e.g. "pgr" for `entire-pgr`). The returned path is not created — that's
97	// the plugin's responsibility on first use.
98	//
99	// Returns an error for names the dispatcher would never invoke (empty,
100	// flag-shaped, agent-protocol-reserved, "."/".." path-traversal, slashes).
101	// This guarantees ENTIRE_PLUGIN_DATA_DIR always points inside the managed
102	// data subtree.
103	func PluginDataDir(name string) (string, error) {
104		if err := validatePluginName(name); err != nil {
105			return "", err
106		}
107		parent, err := pluginParentDir()
108		if err != nil {
109			return "", err
110		}
111		return filepath.Join(parent, pluginManagedDataSubdir, name), nil
112	}
113	
114	// validatePluginName mirrors the dispatcher's isPluginCandidate rules and
115	// returns a descriptive error for invalid names. Used by every entry point
116	// that takes a plugin name from outside the dispatcher (data dir resolution,
117	// managed-dir install).
118	func validatePluginName(name string) error {
119		if name == "" {
120			return errors.New("plugin name is empty")
121		}
122		if strings.HasPrefix(name, "-") {
123			return fmt.Errorf("plugin name %q must not start with '-'", name)
124		}
125		if strings.HasPrefix(name, "agent-") {
126			return fmt.Errorf("plugin name %q is reserved for the external agent protocol", name)
127		}
128		if strings.ContainsAny(name, `/\`) {
129			return fmt.Errorf("plugin name %q must not contain path separators", name)
130		}
131		if name == "." || name == ".." {
132			return fmt.Errorf("plugin name %q is not a valid identifier", name)
133		}
134		return nil
135	}
