137	// EnsurePluginBinDir creates the managed install dir if it doesn't exist.
138	func EnsurePluginBinDir() (string, error) {
139		dir, err := PluginBinDir()
140		if err != nil {
141			return "", err
142		}
143		if err := os.MkdirAll(dir, 0o750); err != nil {
144			return "", fmt.Errorf("create plugin bin dir: %w", err)
145		}
146		return dir, nil
147	}
