149	// PrependPluginBinDirToPATH prepends the managed bin dir to the process's
150	// PATH so the kubectl dispatcher discovers managed-installed plugins.
151	// Idempotent against an already-prepended dir.
152	//
153	// Returns a restore closure the caller invokes to revert PATH to its
154	// previous value. Restoring matters when no plugin runs: built-in commands
155	// and the subprocesses they spawn (git, hooks, less, …) should see the
156	// user's original PATH, not one with the managed plugin dir prepended.
157	// When a plugin *is* dispatched, callers can simply skip the restore — the
158	// process exits anyway, and the plugin child intentionally inherits the
159	// prepended PATH so it can spawn sibling managed plugins.
160	//
161	// Errors and no-op cases (already-prepended, lookup failure) return a
162	// no-op restore so callers always have a safe func to call.
163	func PrependPluginBinDirToPATH() func() {
164		dir, err := PluginBinDir()
165		if err != nil || dir == "" {
166			return func() {}
167		}
168		prev := os.Getenv("PATH")
169		sep := string(os.PathListSeparator)
170		if prev == "" {
171			if err := os.Setenv("PATH", dir); err != nil {
172				return func() {}
173			}
174			return func() { _ = os.Setenv("PATH", "") }
175		}
176		// Idempotent: if the first entry already matches, leave PATH alone.
177		// Windows PATH lookups are case-insensitive (`C:\Foo` and `c:\foo`
178		// resolve identically), so a case-different first entry is the same
179		// dir and we should not double-prepend.
180		first := prev
181		if i := strings.Index(prev, sep); i >= 0 {
182			first = prev[:i]
183		}
184		if pathEntriesEqual(first, dir) {
185			return func() {}
186		}
187		if err := os.Setenv("PATH", dir+sep+prev); err != nil {
188			return func() {}
189		}
190		return func() { _ = os.Setenv("PATH", prev) }
191	}
192	
193	// pathEntriesEqual reports whether two PATH entries refer to the same dir.
194	// filepath.Clean normalizes trailing separators and (on Windows) slash
195	// orientation; case folding handles Windows' case-insensitive lookup.
196	func pathEntriesEqual(a, b string) bool {
197		a = filepath.Clean(a)
198		b = filepath.Clean(b)
199		if runtime.GOOS == windowsGOOS {
200			return strings.EqualFold(a, b)
201		}
202		return a == b
203	}
