205	// InstalledPlugin describes a single entry in the managed bin dir.
206	type InstalledPlugin struct {
207		// Name is the bare plugin name (without the `entire-` prefix and any
208		// platform-specific extension).
209		Name string
210		// Path is the absolute path inside the managed bin dir.
211		Path string
212		// Symlink is true when Path is a symlink to a source location elsewhere
213		// (the typical local-dev install). LinkTarget is populated in that case.
214		Symlink    bool
215		LinkTarget string
216	}
