218	// ListInstalledPlugins enumerates entries in the managed bin dir whose name
219	// starts with `entire-`. Sorted by bare name. A missing dir returns no error
220	// and an empty slice.
221	func ListInstalledPlugins() ([]*InstalledPlugin, error) {
222		dir, err := PluginBinDir()
223		if err != nil {
224			return nil, err
225		}
226		entries, err := os.ReadDir(dir)
227		if err != nil {
228			if errors.Is(err, os.ErrNotExist) {
229				return nil, nil
230			}
231			return nil, fmt.Errorf("read plugin bin dir: %w", err)
232		}
233	
234		var out []*InstalledPlugin
235		for _, e := range entries {
236			full := e.Name()
237			if !strings.HasPrefix(full, pluginBinaryPrefix) {
238				continue
239			}
240			bare := bareNameFromBinaryName(full)
241			if bare == "" {
242				continue
243			}
244			path := filepath.Join(dir, full)
245			info, err := os.Lstat(path)
246			if err != nil {
247				continue
248			}
249			ip := &InstalledPlugin{Name: bare, Path: path}
250			if info.Mode()&os.ModeSymlink != 0 {
251				ip.Symlink = true
252				if target, err := os.Readlink(path); err == nil {
253					ip.LinkTarget = target
254				}
255			}
256			out = append(out, ip)
257		}
258		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
259		return out, nil
260	}
