262	// FindInstalledPlugin returns the entry for the given bare name, or nil if
263	// it isn't installed in the managed dir.
264	func FindInstalledPlugin(name string) (*InstalledPlugin, error) {
265		all, err := ListInstalledPlugins()
266		if err != nil {
267			return nil, err
268		}
269		for _, p := range all {
270			if p.Name == name {
271				return p, nil
272			}
273		}
274		return nil, nil //nolint:nilnil // not-installed signal
275	}
