277	// InstallPluginOptions configures InstallPluginFromPath.
278	type InstallPluginOptions struct {
279		// SourcePath is the absolute (or working-dir-relative) path to the plugin
280		// executable. Its basename — minus any platform extension — must match
281		// `entire-<name>` so the dispatcher can resolve it.
282		SourcePath string
283		// Force replaces an already-installed plugin with the same name.
284		Force bool
285	}
286	
287	// InstallPluginFromPath symlinks SourcePath into the managed bin dir. The
288	// caller is responsible for built-in conflict checks (resolvePlugin already
289	// gates dispatch on rootCmd.Find — installing a name that shadows a built-in
290	// is allowed but the built-in still wins at runtime).
291	//
292	// Refuses names the dispatcher will never invoke (agent-protocol prefix,
293	// flag-shaped, "."/"..", slashes), and refuses self-install when the source
294	// is the same file as the would-be managed entry. The replace step is
295	// atomic: a new symlink is created at <dest>.tmp and renamed onto <dest>,
296	// so a failed --force never leaves the previous install missing.
297	func InstallPluginFromPath(opts InstallPluginOptions) (*InstalledPlugin, error) {
298		src, err := filepath.Abs(opts.SourcePath)
299		if err != nil {
300			return nil, fmt.Errorf("resolve source path: %w", err)
301		}
302		srcInfo, err := os.Stat(src)
303		if err != nil {
304			return nil, fmt.Errorf("stat source: %w", err)
305		}
306		if srcInfo.IsDir() {
307			return nil, fmt.Errorf("source must be a file, got directory: %s", src)
308		}
309		base := filepath.Base(src)
310		bare := bareNameFromBinaryName(base)
311		if bare == "" {
312			return nil, fmt.Errorf("source basename %q must start with %q and have a runnable name", base, pluginBinaryPrefix)
313		}
314		if err := validatePluginName(bare); err != nil {
315			return nil, fmt.Errorf("derived plugin name from %q is not dispatchable: %w", base, err)
316		}
317		if runtime.GOOS != windowsGOOS && srcInfo.Mode()&0o111 == 0 {
318			return nil, fmt.Errorf("source %s is not executable (chmod +x)", src)
319		}
320	
321		binDir, err := EnsurePluginBinDir()
322		if err != nil {
323			return nil, err
324		}
325		dest := filepath.Join(binDir, base)
326	
327		// Reject self-install: the source path already equals the managed
328		// destination path. Without this guard, `--force` would atomically
329		// rename a tmp symlink onto its own target file and the underlying
330		// binary would be unlinked.
331		//
332		// We deliberately do NOT use os.SameFile here. The legitimate
333		// repeat-install case has dest as a symlink we created on a prior
334		// install; SameFile would resolve dest through the symlink to src
335		// and falsely trip. Path equality is the precise risky case.
336		if filepath.Clean(src) == filepath.Clean(dest) {
337			return nil, fmt.Errorf("source %s is already the managed entry; nothing to install", src)
338		}
339	
340		// Conflict check on the bare name (not the exact filename). On Windows,
341		// entire-foo.exe / .bat / .cmd all map to bare name "foo"; checking only
342		// the destination filename would let a second install of a different
343		// extension silently coexist with the first, with PATHEXT ordering then
344		// deciding which one runs. List all variants and require --force when
345		// any exist.
346		conflicts, err := installedVariantsByBareName(bare)
347		if err != nil {
348			return nil, err
349		}
350		if len(conflicts) > 0 && !opts.Force {
351			return nil, fmt.Errorf("plugin %q already installed at %s; use --force to replace", bare, conflicts[0].Path)
352		}
353		// With --force, remove every variant other than the one we're about to
354		// atomically overwrite. The same-extension case is handled by the
355		// rename below, which atomically replaces dest.
356		for _, c := range conflicts {
357			if filepath.Clean(c.Path) == filepath.Clean(dest) {
358				continue
359			}
360			if err := os.Remove(c.Path); err != nil && !errors.Is(err, os.ErrNotExist) {
361				return nil, fmt.Errorf("remove existing variant %s: %w", c.Path, err)
362			}
363		}
364	
365		// Atomic replace via tmp + rename. Rename is atomic on POSIX and
366		// replaces an existing target on Windows (Go's os.Rename uses
367		// MoveFileEx with MOVEFILE_REPLACE_EXISTING). If linking or rename
368		// fails, the previously installed plugin (if any) is unaffected.
369		//
370		// The tmp path uses a random suffix and a `.install-` prefix that does
371		// NOT match `entire-`. This protects against two distinct hazards:
372		//   1. A user can have a legitimate plugin named "foo.tmp" (file
373		//      "entire-foo.tmp"), which a naive `dest + ".tmp"` would clobber.
374		//   2. ListInstalledPlugins filters by `entire-` prefix, so a tmp that
375		//      starts with `.install-` will not appear in `entire plugin list`
376		//      while the install is in progress.
377		tmpDest, err := makeInstallTmpPath(binDir)
378		if err != nil {
379			return nil, err
380		}
381		if err := materializeManagedEntry(src, tmpDest, srcInfo); err != nil {
382			return nil, fmt.Errorf("install plugin: %w", err)
383		}
384		if err := os.Rename(tmpDest, dest); err != nil {
385			_ = os.Remove(tmpDest) // best-effort cleanup; previous install is intact
386			return nil, fmt.Errorf("install plugin: %w", err)
387		}
388		return FindInstalledPlugin(bare)
389	}
390	
391	// installedVariantsByBareName returns every managed entry whose bare name
392	// matches name. On Unix this is at most one entry; on Windows multiple
393	// extensions can map to the same bare name.
394	func installedVariantsByBareName(name string) ([]*InstalledPlugin, error) {
395		all, err := ListInstalledPlugins()
396		if err != nil {
397			return nil, err
398		}
399		var out []*InstalledPlugin
400		for _, p := range all {
401			if p.Name == name {
402				out = append(out, p)
403			}
404		}
405		return out, nil
406	}
407	
408	// makeInstallTmpPath returns a unique scratch path inside binDir for the
409	// in-progress install. The `.install-` prefix is deliberately distinct from
410	// pluginBinaryPrefix so ListInstalledPlugins ignores it; a 16-char hex
411	// suffix from crypto/rand makes collisions vanishingly unlikely and keeps
412	// concurrent installs safe from each other.
413	func makeInstallTmpPath(binDir string) (string, error) {
414		var b [8]byte
415		if _, err := rand.Read(b[:]); err != nil {
416			return "", fmt.Errorf("generate install tmp suffix: %w", err)
417		}
418		return filepath.Join(binDir, ".install-"+hex.EncodeToString(b[:])), nil
419	}
420	
421	// materializeManagedEntry creates dest as a reference to src, falling back
422	// through symlink → hardlink → copy in that order.
423	//
424	// Symlink-first preserves the dev-loop property that rebuilding the source
425	// is immediately reflected in the managed entry. The fallbacks exist for
426	// Windows: os.Symlink there requires Developer Mode or admin, and silently
427	// breaks `entire plugin install` for typical users without either. Mirrors
428	// the pattern in setup_test.go's copyExecutable.
429	//
430	// On a successful copy the file mode of the source is preserved so the
431	// executable bit survives.
432	func materializeManagedEntry(src, dest string, srcInfo os.FileInfo) error {
433		if err := os.Symlink(src, dest); err == nil {
434			return nil
435		}
436		if err := os.Link(src, dest); err == nil {
437			return nil
438		}
439		return copyFileStreaming(src, dest, srcInfo)
440	}
441	
442	// copyFileStreaming copies src to dest in fixed-size buffers, preserving the
443	// source's executable mode. Plugin binaries can be tens of megabytes; using
444	// io.Copy avoids the heap spike of reading the whole file into memory.
445	func copyFileStreaming(src, dest string, srcInfo os.FileInfo) error {
446		mode := srcInfo.Mode().Perm()
447		if mode == 0 {
448			mode = 0o755
449		}
450		in, err := os.Open(src) //nolint:gosec // src is the user-provided plugin executable; reading it is the point
451		if err != nil {
452			return fmt.Errorf("open source for copy fallback: %w", err)
453		}
454		defer in.Close()
455	
456		// G304: dest is always inside the managed bin dir. The basename comes
457		// from a validated plugin name (validatePluginName ran upstream), and
458		// the parent dir comes from EnsurePluginBinDir.
459		out, err := os.OpenFile(dest, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, mode) //nolint:gosec // dest is constrained to the managed bin dir
460		if err != nil {
461			return fmt.Errorf("open destination for copy fallback: %w", err)
462		}
463		if _, err := io.Copy(out, in); err != nil {
464			_ = out.Close()
465			_ = os.Remove(dest)
466			return fmt.Errorf("copy fallback: %w", err)
467		}
468		if err := out.Close(); err != nil {
469			_ = os.Remove(dest)
470			return fmt.Errorf("close destination after copy fallback: %w", err)
471		}
472		return nil
473	}
474	
475	// RemoveInstalledPlugin removes every managed-dir entry whose bare name
476	// matches name. Symlinks are unlinked without touching the source file.
477	//
478	// Iterating all variants matters on Windows, where entire-foo.exe,
479	// entire-foo.bat, and entire-foo.cmd all map to bare name "foo" and could
480	// otherwise leave a runnable variant behind after `entire plugin remove foo`.
481	// On Unix the loop typically runs once.
482	func RemoveInstalledPlugin(name string) error {
483		variants, err := installedVariantsByBareName(name)
484		if err != nil {
485			return err
486		}
487		if len(variants) == 0 {
488			return fmt.Errorf("plugin %q is not installed in the managed directory", name)
489		}
490		for _, p := range variants {
491			if err := os.Remove(p.Path); err != nil && !errors.Is(err, os.ErrNotExist) {
492				return fmt.Errorf("remove plugin entry %s: %w", p.Path, err)
493			}
494		}
495		return nil
496	}
497	
498	// bareNameFromBinaryName turns a plugin executable's basename into the bare
499	// name the dispatcher uses (e.g. "entire-pgr" → "pgr"). Returns "" if the
500	// input doesn't match the expected shape.
501	//
502	// Extension stripping is platform-conditional:
503	//
504	//   - On Windows, .exe/.bat/.cmd are the natural extensions for executables
505	//     and exec.LookPath resolves them via PATHEXT, so we strip them so the
506	//     bare name a user types ("pgr") matches both the managed-list display
507	//     and the dispatcher's lookup.
508	//
509	//   - On Unix, exec.LookPath matches the exact filename. If we stripped here,
510	//     "entire-pgr.exe" would be listed as "pgr" and the user would type
511	//     "entire pgr", but the dispatcher's exec.LookPath("entire-pgr") would
512	//     not find "entire-pgr.exe". Leaving the dot in place keeps the listed
513	//     name aligned with the only invocation that actually resolves
514	//     ("entire pgr.exe"), avoiding silent shadowing surprises.
515	func bareNameFromBinaryName(base string) string {
516		if !strings.HasPrefix(base, pluginBinaryPrefix) {
517			return ""
518		}
519		cleaned := base
520		if runtime.GOOS == windowsGOOS {
521			// Reuse the canonical Windows-executable-extension list from
522			// agent/external rather than maintaining a parallel copy. plugin.go
523			// already depends on this package for isAgentProtocolBinary, so
524			// there's no new layering cost.
525			cleaned = external.StripExeExt(base)
526		}
527		bare := strings.TrimPrefix(cleaned, pluginBinaryPrefix)
528		if bare == "" {
529			return ""
530		}
531		return bare
532	}
