21	// External-command resolution, kubectl-style. When the user invokes
22	// `entire <name>` and <name> isn't a built-in subcommand, look for an
23	// `entire-<name>` binary on PATH and exec it with the remaining args.
24	// Stdio and exit codes pass through. Binaries matching the agent
25	// protocol prefix are reserved for the external agent registry and
26	// skipped here.
27	const (
28		pluginBinaryPrefix      = "entire-"
29		agentPluginBinaryPrefix = "entire-agent-"
30	)
31	
32	// MaybeRunPlugin returns (true, exitCode) when an external command was
33	// resolved and run. On launch failure (e.g. missing executable bit)
34	// returns (true, 1) after printing to stderr. On no-match returns
35	// (false, 0) so the caller can fall through to Cobra.
36	//
37	// Telemetry and the version-check notice mirror Cobra's PersistentPostRun
38	// behavior for built-ins: both fire only on a successful (exit-0) run.
39	func MaybeRunPlugin(ctx context.Context, rootCmd *cobra.Command, args []string) (handled bool, exitCode int) {
40		binPath, pluginArgs, ok := resolvePlugin(rootCmd, args)
41		if !ok {
42			return false, 0
43		}
44		pluginName := args[0]
45		exitCode = runPlugin(ctx, pluginName, binPath, pluginArgs)
46		if exitCode == 0 {
47			maybeTrackPluginInvocation(ctx, pluginName)
48			versioncheck.CheckAndNotify(ctx, os.Stdout, versioninfo.Version)
49		}
50		return true, exitCode
51	}
52	
53	// maybeTrackPluginInvocation fires telemetry only for plugins on the
54	// official allowlist. Third-party plugin names are never sent — see
55	// IsOfficialPlugin for the rationale.
56	func maybeTrackPluginInvocation(ctx context.Context, pluginName string) {
57		if !IsOfficialPlugin(pluginName) {
58			return
59		}
60		s, err := LoadEntireSettings(ctx)
61		if err != nil {
62			return
63		}
64		if s.Telemetry == nil || !*s.Telemetry {
65			return
66		}
67		telemetry.TrackPluginDetached(pluginName, s.Enabled, versioninfo.Version)
68	}
