70	func resolvePlugin(rootCmd *cobra.Command, args []string) (binPath string, pluginArgs []string, ok bool) {
71		if len(args) == 0 {
72			return "", nil, false
73		}
74		name := args[0]
75		if !isPluginCandidate(name) {
76			return "", nil, false
77		}
78		// Cobra adds `help` and `completion` to the command tree inside Execute,
79		// not in the constructor / SetHelpCommand. Without priming them, Find
80		// reports "unknown command" for those names and an entire-help (or
81		// entire-completion) binary on PATH would shadow the built-in. Both
82		// initializers are idempotent and Execute calls them again later.
83		rootCmd.InitDefaultHelpCmd()
84		rootCmd.InitDefaultCompletionCmd(args...)
85		// Built-in commands always win.
86		if cmd, _, err := rootCmd.Find(args); err == nil && cmd != rootCmd {
87			return "", nil, false
88		}
89		binName := pluginBinaryPrefix + name
90		binPath, err := exec.LookPath(binName)
91		if err != nil {
92			// LookPath conflates "not on PATH" with "found but not executable".
93			// Distinguish: if a file with this name exists on PATH but isn't
94			// executable, surface that as a launch error rather than falling
95			// through to Cobra's generic unknown-command path.
96			if p, found := findInaccessiblePlugin(binName); found {
97				return p, args[1:], true
98			}
99			return "", nil, false
100		}
101		if isAgentProtocolBinary(binPath) {
102			return "", nil, false
103		}
104		return binPath, args[1:], true
105	}
106	
107	// findInaccessiblePlugin scans PATH for a non-directory file with the
108	// given name. Only meaningful after exec.LookPath has already failed —
109	// indicates the file exists but lacks the executable bit (or the
110	// equivalent platform-specific accessibility).
111	func findInaccessiblePlugin(filename string) (string, bool) {
112		for _, dir := range filepath.SplitList(os.Getenv("PATH")) {
113			if dir == "" {
114				continue
115			}
116			candidate := filepath.Join(dir, filename)
117			info, err := os.Stat(candidate) //nolint:gosec // PATH entries are user-trusted; scanning them is the point.
118			if err != nil || info.IsDir() {
119				continue
120			}
121			return candidate, true
122		}
123		return "", false
124	}
125	
126	func isPluginCandidate(name string) bool {
127		if name == "" {
128			return false
129		}
130		if strings.HasPrefix(name, "-") {
131			return false
132		}
133		// `agent-*` is reserved for the external agent protocol.
134		if strings.HasPrefix(name, "agent-") {
135			return false
136		}
137		if strings.ContainsAny(name, `/\`) {
138			return false
139		}
140		// "." and ".." would collapse out of any joined path (e.g. for
141		// ENTIRE_PLUGIN_DATA_DIR), breaking the per-plugin isolation contract.
142		if name == "." || name == ".." {
143			return false
144		}
145		return true
146	}
147	
148	// isAgentProtocolBinary returns true when the binary name is reserved for
149	// the external agent protocol. Strip Windows extensions first so
150	// `entire-agent-foo.exe` is also recognized.
151	func isAgentProtocolBinary(binPath string) bool {
152		base := external.StripExeExt(filepath.Base(binPath))
153		return strings.HasPrefix(base, agentPluginBinaryPrefix)
154	}
155	
156	// runPlugin executes the resolved plugin binary, propagating its exit code.
157	// On context cancellation the child gets SIGINT (with a 5s grace before the
158	// runtime falls back to SIGKILL) so plugins can clean up. Terminal signals
159	// reach the child directly via the shared process group.
160	func runPlugin(ctx context.Context, pluginName, binPath string, args []string) int {
161		cmd := exec.CommandContext(ctx, binPath, args...)
162		cmd.Cancel = func() error { return cmd.Process.Signal(os.Interrupt) }
163		cmd.WaitDelay = 5 * time.Second
164		cmd.Stdin = os.Stdin
165		cmd.Stdout = os.Stdout
166		cmd.Stderr = os.Stderr
167		extras := []string{"ENTIRE_CLI_VERSION=" + versioninfo.Version}
168		if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
169			extras = append(extras, "ENTIRE_REPO_ROOT="+repoRoot)
170		}
171		// Per-plugin durable storage. Passed regardless of where the binary lives
172		// so plugins installed via raw PATH and via `entire plugin install` get
173		// the same contract. The dir is not pre-created — that's the plugin's
174		// responsibility on first use.
175		//
176		// PluginDataDir can only fail in degenerate environments (e.g. no
177		// resolvable home dir). The plugin name itself has already passed
178		// isPluginCandidate validation in resolvePlugin, so the validator
179		// branch can't fire here. We warn-and-proceed rather than refuse to
180		// launch: a HOME-less environment is the user's problem to surface,
181		// not a reason to break plugins that don't read the var.
182		parentEnv := os.Environ()
183		if dataDir, err := PluginDataDir(pluginName); err == nil {
184			extras = append(extras, pluginEnvPluginData+"="+dataDir)
185		} else {
186			// Strip any inherited value so the warning's "not set" claim
187			// matches reality. Otherwise a user with ENTIRE_PLUGIN_DATA_DIR
188			// pre-set in their shell would silently see that value reach the
189			// plugin even though we logged the opposite (ENTIRE_* is in the
190			// pluginEnv allowlist prefix, so without this strip the inherited
191			// value would pass through).
192			parentEnv = removeEnvKey(parentEnv, pluginEnvPluginData)
193			fmt.Fprintf(os.Stderr, "warning: ENTIRE_PLUGIN_DATA_DIR not set for plugin %q: %v\n", pluginName, err)
194		}
195		cmd.Env = pluginEnv(parentEnv, extras...)
196	
197		if err := cmd.Run(); err != nil {
198			var exitErr *exec.ExitError
199			if errors.As(err, &exitErr) {
200				return exitErr.ExitCode()
201			}
202			// Prefix with the plugin name so users can tell parent vs child
203			// errors apart in mixed stderr.
204			fmt.Fprintf(os.Stderr, "Failed to run plugin %s: %v\n", filepath.Base(binPath), err)
205			return 1
206		}
207		return 0
208	}
