194	func TestBareNameFromBinaryName(t *testing.T) {
195		t.Parallel()
196		// Cases that hold on every platform.
197		common := map[string]string{
198			"entire-pgr": "pgr",
199			"entire-":    "",
200			"foo":        "",
201			"":           "",
202		}
203		for in, want := range common {
204			if got := bareNameFromBinaryName(in); got != want {
205				t.Errorf("bareNameFromBinaryName(%q) = %q; want %q", in, got, want)
206			}
207		}
208		// Platform-conditional: extensions are stripped only on Windows so a
209		// managed entry actually resolves at runtime via exec.LookPath.
210		if runtime.GOOS == windowsGOOS {
211			for in, want := range map[string]string{
212				"entire-pgr.exe": "pgr",
213				"entire-foo.bat": "foo",
214				"entire-foo.cmd": "foo",
215			} {
216				if got := bareNameFromBinaryName(in); got != want {
217					t.Errorf("[windows] bareNameFromBinaryName(%q) = %q; want %q", in, got, want)
218				}
219			}
220		} else {
221			// On Unix, a .exe basename is *not* a valid bare name — installing
222			// it would yield a managed entry that LookPath would never match.
223			// We accept that bareNameFromBinaryName may return a non-empty
224			// string here (the dispatcher uses exact-match LookPath); the
225			// guarantee we test is that "entire-pgr.exe" doesn't collapse to
226			// "pgr" on Unix.
227			if got := bareNameFromBinaryName("entire-pgr.exe"); got == "pgr" {
228				t.Errorf("[unix] bareNameFromBinaryName(entire-pgr.exe) collapsed to %q; should not strip .exe on Unix", got)
229			}
230		}
231	}
